const row = $('Get row(s) in sheet').first().json;
const title = row.Title || 'Untitled Blog';
const tags = String(row.Tags || '').split(',').map(t => t.trim()).filter(Boolean);

let content = '';
try {
  const agentOutput = $('AI Agent').first().json;
  content = agentOutput.output || agentOutput.text || agentOutput.content || '';
} catch (e) {
  content = '';
}
content = String(content).trim().replace(/^```[\w]*\n?/gm, '').replace(/^```$/gm, '').trim();

const slug = (row.Slug || title)
  .toLowerCase()
  .trim()
  .replace(/[^\w\s-]/gi, '')
  .replace(/\s+/g, '-')
  .replace(/-+/g, '-')
  .replace(/^-|-$/g, '');

const photos = $('Pexels Image Search').first().json?.photos || [];
const coverImage = photos[0]?.src?.large2x || '';

return [{
  json: {
    title,
    slug,
    description: content.slice(0, 155).replace(/[#*\n]/g, ' ').trim(),
    content,
    coverImage,
    tags,
  }
}];
